scalated], input_bindings={earlier_decision,affected_item,later_discrepancy,operational_effect,text})\n)\ncomponent_records := (\n  SCAN_TABLE(NASA_ASRS, components.csv, [incident_id, attribute, value])\n  -> FILTER(attribute IN ('aircraft_component','problem'))\n  -> GROUP_BY([incident_id], {structured_components:COLLECT_IF(value,attribute='aircraft_component'), structured_problems:COLLECT_IF(value,attribute='problem')})\n)\njoined := JOIN(left=semantic_chains, right=component_records, join_type=inner, condition=semantic_chains.incident_id = component_records.incident_id)\njoined\n-> GROUP_BY([maintenance_status,discovery_phase,chain_category], {incident_count:COUNT_DISTINCT(incident_id), chain_records:COLLECT(affected_item,later_discrepancy,structured_components,structured_problems)})\n-> SEM_AGGREGATE(\"For each group, provide one canonical affected item and recurring discrepancy, each in at most six words.\", {canonical_affected_item:string, recurring_discrepancy:string}, group_by=[maintenance_status,discovery_phase,chain_category], input_bindings={chain_records})\n-> ORDER_BY([incident_count DESC, maintenance_status ASC, discovery_phase ASC, chain_category ASC])\n-> LIMIT(12)\n-> PROJECT([rank=ROW_NUMBER(),maintenance_status,discovery_phase,chain_category,incident_count,canonical_affected_item,recurring_discrepancy])"
